var toolbar = new ArcFilterToolbar
{
    Label = "Project filters",
    SearchText = string.Empty,
    SearchPlaceholder = "Search projects",
    ResultCount = 128,
    ResultLabel = "projects",
    SortKey = "updated",
    Filters = new[]
    {
        new ArcFilterChip { Id = "status", Label = "Status", Value = "Open" },
        new ArcFilterChip { Id = "owner", Label = "Owner", Value = "Maya" }
    },
    Fields = new[]
    {
        new ArcFilterField
        {
            Id = "status",
            Label = "Status",
            Options = new List<ArcFilterOption>
            {
                new() { Value = "Open" },
                new() { Value = "Closed" },
                new() { Value = "Blocked" }
            }
        }
    },
    SortOptions = new[]
    {
        new ArcSortOption { Key = "updated", Label = "Last updated" },
        new ArcSortOption { Key = "name", Label = "Name" }
    }
};

toolbar.SearchChanged += (_, text) => Reload(query: text);
toolbar.FilterAdded += (_, chip) => AddFilter(chip.Id, chip.Value);
toolbar.FilterRemoved += (_, id) => RemoveFilter(id);
toolbar.ClearAllRequested += (_, _) => ResetFilters();
toolbar.SortChanged += (_, key) => SortBy(key);
